@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{font-family:'DM Sans',sans-serif;color:#e9f0ff;background:#080d19;font-synthesis:none;text-rendering:optimizeLegibility;--bg:#080d19;--panel:#0d1525;--panel2:#111d32;--line:rgba(151,178,222,.12);--muted:#8291aa;--blue:#4d8dff;--cyan:#4bd7ef}
*{box-sizing:border-box}body{margin:0;min-width:320px;background:radial-gradient(ellipse at 55% -25%,rgba(35,91,174,.18),transparent 55%),var(--bg)}button,textarea{font:inherit}button{cursor:pointer;color:inherit}.app-shell{height:100dvh;display:flex;overflow:hidden}.sidebar{width:260px;flex-shrink:0;background:rgba(9,15,27,.96);border-right:1px solid var(--line);padding:23px 16px 15px;display:flex;flex-direction:column;z-index:5}.brand{display:flex;align-items:center;gap:11px;padding:0 7px 28px}.brand-mark{width:39px;height:39px;border-radius:13px;display:grid;place-items:center;font:700 25px 'Space Grotesk';background:linear-gradient(140deg,#42d0f4,#526dff);color:#071326;box-shadow:0 5px 24px #2565b855}.brand strong{font:700 20px 'Space Grotesk';letter-spacing:-.8px}.brand strong span{color:#5ab9ff}.brand small{display:block;color:#65748d;font-size:8px;letter-spacing:1.7px;margin-top:1px}.new-chat{height:43px;border:1px solid rgba(80,143,255,.28);border-radius:10px;background:linear-gradient(100deg,rgba(42,103,201,.2),rgba(29,64,121,.12));display:flex;align-items:center;gap:10px;padding:0 12px;color:#dbeaff;font-weight:600}.new-chat svg{color:#69baff}.new-chat kbd{margin-left:auto;color:#8294ae;font-size:10px;background:#15233a;padding:3px 5px;border-radius:4px}.side-label{font-size:9px;letter-spacing:1.7px;color:#61718c;margin:29px 9px 10px}.chat-list{display:flex;flex-direction:column;gap:4px;overflow:auto}.history-item{display:flex;align-items:center;gap:9px;border:0;background:transparent;text-align:left;color:#93a2ba;border-radius:8px;padding:10px 9px;font-size:12px}.history-item.active,.history-item:hover{background:#14223a;color:#e7f1ff}.history-title{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:1}.delete-chat{opacity:0;color:#8392aa}.history-item:hover .delete-chat{opacity:1}.sidebar-bottom{margin-top:auto}.status{display:flex;align-items:center;gap:10px;padding:12px 9px;border:1px solid var(--line);border-radius:10px;background:#0d1729}.status>span,.secure-pill>span{width:7px;height:7px;background:#36d6a0;border-radius:50%;box-shadow:0 0 10px #36d6a0}.status b{font-size:11px;display:block}.status small{font-size:10px;color:#71829c}.sidebar-foot{font-size:10px;color:#5c6c85;text-align:center;margin-top:13px}.main{min-width:0;flex:1;display:flex;flex-direction:column}.topbar{height:65px;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 29px;justify-content:space-between;flex-shrink:0}.top-title{font-size:12px;color:#8594ac}.top-title span{color:#3d4b62;padding:0 7px}.top-title b{color:#dce8fa;font-weight:600}.top-right{display:flex;align-items:center;gap:13px}.secure-pill{display:flex;align-items:center;gap:7px;font-size:10px;color:#9aabc4;border:1px solid var(--line);border-radius:30px;padding:7px 10px}.secure-pill>span{width:6px;height:6px}.profile{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(140deg,#2e91c6,#4c5de1);font-weight:700;font-family:'Space Grotesk'}.mobile-menu,.close-sidebar{display:none;background:none;border:0}.chat-area{flex:1;overflow:hidden;display:flex;justify-content:center}.messages{width:min(850px,100%);padding:34px 32px 24px;overflow:auto;scroll-behavior:smooth}.welcome{max-width:650px;margin:7vh auto 0;text-align:center}.welcome-logo{position:relative;margin:0 auto 20px;width:62px;height:62px;border-radius:21px;background:linear-gradient(140deg,#42c9e9,#526cff);display:grid;place-items:center;box-shadow:0 8px 50px #2d80f64c}.welcome-logo span{font:700 39px 'Space Grotesk';color:#06152c}.glow-dot{position:absolute;width:8px;height:8px;border-radius:50%;background:#b7f5ff;right:8px;top:8px;box-shadow:0 0 13px #fff}.eyebrow{font-size:9px;letter-spacing:2.6px;color:#5da9ff;font-weight:700}.welcome h1{font:600 clamp(32px,5vw,48px)/1.12 'Space Grotesk';letter-spacing:-2px;margin:13px 0;color:#f1f6ff}.welcome h1 em{font-style:normal;background:linear-gradient(90deg,#61c9f4,#7185ff);-webkit-background-clip:text;background-clip:text;color:transparent}.welcome p{max-width:440px;margin:0 auto;color:#8999b3;font-size:13px;line-height:1.7}.suggestions{display:flex;flex-wrap:wrap;justify-content:center;gap:9px;margin:31px auto 0}.suggestions button{display:flex;align-items:center;gap:8px;background:#101c30;border:1px solid var(--line);border-radius:9px;padding:11px 13px;font-size:11px;color:#b8c8df}.suggestions button:hover{border-color:#428bdf;background:#142541}.suggestions svg{color:#65baff}.message{display:flex;gap:13px;margin:0 auto 28px;max-width:740px;align-items:flex-start}.avatar{width:30px;height:30px;border-radius:10px;flex-shrink:0;display:grid;place-items:center;font:700 16px 'Space Grotesk'}.ai-avatar{background:linear-gradient(140deg,#40c9eb,#536aff);color:#07142b}.user-avatar{background:#1c2c46;color:#b8d8ff}.message-body{min-width:0;flex:1;padding-top:2px}.message-label{font-size:11px;font-weight:700;color:#b9c9df;margin-bottom:8px}.message.user .message-label{color:#85b8ff}.message-text{font-size:13px;line-height:1.8;color:#d0dced;overflow-wrap:anywhere}.message-text h2,.message-text h3{font-family:'Space Grotesk';color:#f0f6ff}.message-text h2{font-size:19px}.message-text h3{font-size:16px}.message-text ul{padding-left:20px}.message-text li{padding:2px 0}.message-text pre{background:#07101e;border:1px solid var(--line);border-radius:9px;padding:13px;overflow:auto}.message-text code{background:#17243a;border-radius:4px;padding:2px 5px;font-size:12px}.copy-btn{display:flex;align-items:center;gap:6px;background:transparent;border:0;color:#7789a5;font-size:10px;padding:8px 0}.sources{border-top:1px solid var(--line);margin-top:15px;padding-top:11px;display:flex;flex-wrap:wrap;gap:8px}.sources-title{width:100%;display:flex;align-items:center;gap:6px;font-size:10px;color:#7daee9;font-weight:700}.sources a{display:inline-flex;align-items:center;gap:5px;max-width:100%;color:#9bbde9;background:#101e33;border:1px solid var(--line);padding:6px 8px;border-radius:6px;text-decoration:none;font-size:10px;overflow-wrap:anywhere}.sources a:hover{border-color:#4e8bd8}.typing{display:flex;gap:5px;padding:10px 0}.typing i{width:6px;height:6px;border-radius:50%;background:#5daaff;animation:pulse 1s infinite alternate}.typing i:nth-child(2){animation-delay:.2s}.typing i:nth-child(3){animation-delay:.4s}@keyframes pulse{to{opacity:.25;transform:translateY(-3px)}}.composer-wrap{width:min(850px,100%);padding:0 32px 16px;margin:0 auto;flex-shrink:0}.composer{background:#101a2c;border:1px solid rgba(117,160,224,.22);border-radius:15px;padding:13px 14px 10px;box-shadow:0 12px 45px #0005}.composer:focus-within{border-color:#428cdb;box-shadow:0 0 0 3px #347bdb18}.composer textarea{width:100%;resize:none;border:0;outline:0;background:transparent;color:#eaf2ff;font-size:13px;line-height:1.5;min-height:30px;max-height:160px}.composer textarea::placeholder{color:#6f809b}.composer-tools{display:flex;align-items:center;justify-content:space-between;margin-top:8px}.tool-left{display:flex;align-items:center;gap:10px}.web-toggle{display:flex;align-items:center;gap:6px;border:1px solid var(--line);background:#142137;border-radius:7px;padding:6px 8px;color:#8598b5;font-size:10px}.web-toggle.selected{color:#a9d6ff;border-color:#326fba;background:#142b49}.toggle-dot{width:6px;height:6px;border-radius:50%;background:#45556d}.selected .toggle-dot{background:#55c6ff;box-shadow:0 0 7px #55c6ff}.tool-note{font-size:9px;color:#64758f}.send-btn{width:33px;height:33px;border:0;border-radius:9px;background:linear-gradient(135deg,#42bfe7,#536aff);display:grid;place-items:center;color:#06152b}.send-btn:disabled{opacity:.45;cursor:default}.disclaimer{text-align:center;color:#586982;font-size:9px;margin-top:10px}.close-sidebar{margin-left:auto;font-size:23px;color:#9bacbf}.mobile-menu{color:#a9bdd7}.mobile-menu svg{display:block}@media(max-width:760px){.sidebar{position:fixed;inset:0 auto 0 0;width:280px;transform:translateX(-105%);transition:transform .22s ease;box-shadow:20px 0 60px #0008}.sidebar.open{transform:translateX(0)}.close-sidebar{display:block}.topbar{height:56px;padding:0 15px;justify-content:flex-start;gap:12px}.top-right{margin-left:auto}.secure-pill{display:none}.messages{padding:24px 17px}.welcome{margin-top:9vh}.welcome h1{font-size:37px}.suggestions{flex-direction:column;align-items:stretch;max-width:330px}.suggestions button{justify-content:flex-start}.composer-wrap{padding:0 12px 12px}.tool-note{display:none}.message{gap:9px}.avatar{width:28px;height:28px}.disclaimer{font-size:8px}.top-title{font-size:11px}}@media(min-width:761px){.mobile-menu{display:none!important}}
